package com.afterglow.player;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
public class QueueEditChecks extends Instrumentation {
 interface Condition{boolean ok();}void await(Condition c,int seconds)throws Exception{for(int i=0;i<seconds*20;i++){if(c.ok())return;Thread.sleep(50);}throw new AssertionError("Timed out");}void check(boolean ok,String label){if(!ok)throw new AssertionError(label);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 Button find(View v,String label){if(v instanceof Button&&label.contentEquals(((Button)v).getText()))return (Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=find(((ViewGroup)v).getChildAt(i),label);if(b!=null)return b;}return null;}
 public void onStart(){Bundle result=new Bundle();try{MainActivity a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(()->a.service!=null,10);PlaybackService p=a.service;
 runOnMainSync(()->{p.pause(true);p.releasePlayer();p.queue.clear();p.upcoming.clear();p.backlog.clear();p.repeat=p.repeatAll=false;p.index=0;for(int i=0;i<14;i++)p.queue.add(new Track("Queue edit check "+i,"Original demo","demo","local"));p.playSequence(new ArrayList<>(p.queue),false);});await(()->p.playing()&&p.nextPrepared,12);Track current=p.current();android.media.MediaPlayer player=p.player;
 runOnMainSync(()->{check(p.upcoming.size()==10&&p.backlog.size()==3,"Initial playlist window");Track removed=p.upcoming.get(0);p.dequeue(removed);check(p.upcoming.size()==9&&p.backlog.size()==3,"Removal leaves empty slot");p.moveTrack(p.upcoming.get(1),0);p.shuffleUpcoming();p.queueChanged();p.refreshUpcoming();check(p.upcoming.size()==9&&p.backlog.size()==3,"Reorder, shuffle and callbacks do not refill");check(!p.upcoming.contains(removed)&&!p.backlog.contains(removed),"Removed track stays removed");check(p.current()==current&&p.player==player&&p.playing(),"Removal preserves playback");});
 Track next=p.upcoming.get(0);runOnMainSync(()->p.seek(p.duration()-600));await(()->p.current()==next&&p.playing(),8);check(p.upcoming.size()==10&&p.backlog.size()==1,"Playback advancement still replenishes playlist");android.media.MediaPlayer playing=p.player;Track selected=p.current();
 runOnMainSync(()->{p.repeatAll=true;p.save();a.showQueue();Button clear=find(a.queueRows,"Clear queue");check(clear!=null,"Clear queue button exists");clear.performClick();check(p.upcoming.isEmpty()&&p.backlog.isEmpty(),"Clear removes visible and deferred songs");check(!p.repeatAll,"Clear prevents repeat-all refill");check(p.player==playing&&p.current()==selected&&p.playing(),"Clear keeps current playback");check(p.nextPlayer==null,"Prepared next released");check(p.queue.size()==14,"Library untouched");check("[]".equals(p.prefs.getString("upcoming",""))&&"[]".equals(p.prefs.getString("backlog","")),"Empty queue persisted");p.queueChanged();p.refreshUpcoming();check(p.upcoming.isEmpty(),"Queue remains empty after refresh");a.queueDialog.dismiss();p.seek(p.duration()-500);});await(()->p.ended,7);check(p.upcoming.isEmpty()&&p.backlog.isEmpty()&&!p.playing(),"No new track after cleared queue ends");
 result.putString("result","PASS: removal/shuffle/reorder do not refill; advancement still refills; Clear queue preserves playback/library, releases next, persists empty backlog and stops after current song");
 }catch(Throwable e){result.putString("failure",e.toString());}finish(result.containsKey("failure")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}
